  -- Only revoke if a non-superuser app role exists
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_user') THEN
    EXECUTE 'REVOKE UPDATE, DELETE ON audit_events FROM app_user';
  END IF;
END $$;

