import { spawnSync } from "node:child_process";
import { resolve } from "node:path";

/**
 * Vitest globalSetup for `@reading-advantage/auth` integration tests.
 *
 * Runs the Drizzle migration runner against the resolved test database
 * exactly once per test run, by spawning `node` (which is on PATH) to run
 * `drizzle-kit/bin.cjs migrate`. Drizzle migrations are idempotent.
 *
 * Test-DB resolution mirrors `apps/science-advantage/lib/test/resolve-test-database-url.ts`:
 *   1. `TEST_DATABASE_URL` — used verbatim.
 *   2. `DATABASE_URL` with `_test` appended to the pathname.
 *   3. Built-in default: `postgresql://postgres:postgres@localhost:5432/science_advantage_test`.
 *
 * The migration role (typically `postgres` locally) is the only one with
 * DELETE on `audit_events`, satisfying the append-only REVOKE — see
 * `measure/tracks/audit_log_retention_dsar_20260605/test-strategy.md` §1.
 *
 * Implementation note:
 *   This file intentionally avoids spawning `pnpm --filter @reading-advantage/db migrate`
 *   because pnpm lives in the corepack shim dir and is not always on PATH
 *   inside spawned subprocesses. Calling drizzle-kit directly via node keeps
 *   the global setup fast and PATH-independent.
 *
 *   A 60s timeout guards against a hung migration (e.g., if the DB is
 *   unreachable). If the migration cannot complete in that window, the
 *   global setup throws and vitest exits cleanly with a clear signal.
 */
function resolveTestDatabaseUrl(env: {
  DATABASE_URL?: string;
  TEST_DATABASE_URL?: string;
}): string {
  if (env.TEST_DATABASE_URL) return env.TEST_DATABASE_URL;
  const primary = env.DATABASE_URL ?? "postgresql://postgres:postgres@localhost:5432/science_advantage";
  if (primary.endsWith("_test")) return primary;
  try {
    const url = new URL(primary);
    const pathname = url.pathname.replace(/\/$/, "");
    url.pathname = `${pathname}_test`;
    return url.toString();
  } catch {
    return `${primary}_test`;
  }
}

export default function globalSetup(): void {
  const databaseUrl = resolveTestDatabaseUrl(process.env);

  // Sanity check: confirm the URL parses before we hand it to drizzle-kit.
  try {
    new URL(databaseUrl);
  } catch (error) {
    throw new Error(
      `[auth vitest.integration.global-setup] invalid test DB URL: ${databaseUrl} (${
        error instanceof Error ? error.message : "unknown error"
      })`,
    );
  }

  // Resolve the drizzle-kit binary that ships with @reading-advantage/db.
  // `packages/auth/node_modules/@reading-advantage/db` is a workspace
  // symlink to `packages/db`, so the path is stable across the monorepo.
  const dbPackageRoot = resolve(__dirname, "../../db");
  const drizzleKitBin = resolve(dbPackageRoot, "node_modules/drizzle-kit/bin.cjs");

  const result = spawnSync(
    "node",
    [drizzleKitBin, "migrate"],
    {
      stdio: "inherit",
      env: { ...process.env, DATABASE_URL: databaseUrl },
      cwd: dbPackageRoot,
      timeout: 60_000,
    },
  );

  if (result.signal) {
    throw new Error(
      `[auth vitest.integration.global-setup] drizzle-kit migrate killed by signal ${result.signal} (DATABASE_URL=${databaseUrl}). ` +
        `Common causes: DB unreachable, drizzle-kit hung, or timeout (>60s).`,
    );
  }
  if (result.status !== 0) {
    throw new Error(
      `[auth vitest.integration.global-setup] drizzle-kit migrate exited with status ${result.status} (DATABASE_URL=${databaseUrl}).`,
    );
  }

  // The purge function reads DIRECT_DATABASE_URL for the privileged connection
  // (DELETE on audit_events). The migration role and the privileged role are
  // the same in local dev (the `postgres` superuser). Setting both keeps the
  // app connection and the privileged connection pointed at the same DB.
  process.env.DIRECT_DATABASE_URL = databaseUrl;
}

