 * explicit prerequisite for the integration test suite and must be run by
 * the developer/CI before invoking vitest:
 *
 *   DATABASE_URL=postgresql://postgres:postgres@localhost:5432/science_advantage_test \
 *     pnpm --filter @reading-advantage/db migrate
 *
 * The test file asserts the table exists by attempting a `TRUNCATE`; if the
 * migration was not run, every test fails with a `relation "audit_events"
 * does not exist` error. That is the Red-phase signal for missing infra
 * (per `measure/tracks/audit_log_retention_dsar_20260605/test-strategy.md` §1).
 *
 * Test-DB resolution mirrors `apps/science-advantage/lib/test/resolve-test-database-url.ts`:
 *   1. `TEST_DATABASE_URL` — used verbatim.
 *   2. `DATABASE_URL` with `_test` appended to the pathname.
 *   3. Built-in default: `postgresql://postgres:postgres@localhost:5432/science_advantage_test`.
 *
 * The migration role (typically `postgres` locally) is the only one with
 * DELETE on `audit_events`, satisfying the append-only REVOKE.
 */
function resolveTestDatabaseUrl(env: {
  DATABASE_URL?: string;
  TEST_DATABASE_URL?: string;
}): string {
  if (env.TEST_DATABASE_URL) return env.TEST_DATABASE_URL;
  const primary = env.DATABASE_URL ?? "postgresql://postgres:postgres@localhost:5432/science_advantage";
  if (primary.endsWith("_test")) return primary;
  try {
    const url = new URL(primary);
    const pathname = url.pathname.replace(/\/$/, "");
    url.pathname = `${pathname}_test`;
    return url.toString();
  } catch {
    return `${primary}_test`;
  }
}

export default function globalSetup(): void {
  const databaseUrl = resolveTestDatabaseUrl(process.env);

  // Sanity check: confirm the URL parses.
  try {
    new URL(databaseUrl);
  } catch (error) {
    throw new Error(
      `[auth vitest.integration.global-setup] invalid test DB URL: ${databaseUrl} (${
        error instanceof Error ? error.message : "unknown error"
      })`,
    );
  }

  // Point both the app connection and the privileged connection at the test
  // DB. The migration role and the privileged role are the same in local dev
  // (the `postgres` superuser); in production they would be a dedicated
  // maintenance role with DELETE on `audit_events`.
  process.env.DATABASE_URL = databaseUrl;
  process.env.DIRECT_DATABASE_URL = databaseUrl;
}

